{"command": "cd /workspace && python3 - <<'PY'
import json

rec = {
  "row_id": "C0000-17",
  "source_sku": "SKU-0000-17",
  "source": "distributor",
  "brand": "Lumen Electronics",
  "model": "pd-100",
  "category": "charger",
  "pack_size": "1 pcs",
  "title": "Lumen PD100 new edition",
  "attributes": {"power": "100000 mW", "connector": "usb c"}
}
brand_aliases = {"LUMEN":"Lumen","ORION":"Orion","HALO":"Halo","ZEPHYR":"Zephyr",
 "Lumen Electronics":"Lumen","Orion Electronics":"Orion","Halo Electronics":"Halo","Zephyr Electronics":"Zephyr"}
source_priority = {"manufacturer":0,"distributor":1,"marketplace":2}
attr_aliases = {"usb c":"USB-C","USB-C":"USB-C","nvme":"NVMe","NVMe":"NVMe"}

brand = brand_aliases.get(rec["brand"], rec["brand"])
model = rec["model"].upper().replace(" ","").replace("-","")

# pack_size -> integer
ps = rec["pack_size"]
if isinstance(ps,str) and ps.strip().endswith("pcs"):
    pack = int(ps.split()[0])
else:
    pack = int(ps)

attrs = {}
for k,v in rec["attributes"].items():
    kl = k.lower()
    if kl == "capacity":
        if isinstance(v,str) and v.strip().upper().endswith("TB"):
            attrs["capacity_gb"] = int(float(v.split()[0])*1000)
        else:
            attrs["capacity_gb"] = int(float(str(v).split()[0]))
    elif kl == "length":
        s=str(v).strip().lower()
        if s.endswith("mm"): attrs["length_mm"]=int(float(s[:-2]))
        elif s.endswith("cm"): attrs["length_mm"]=int(float(s[:-2])*10)
        elif s.endswith("m"): attrs["length_mm"]=int(float(s[:-1])*1000)
    elif kl == "power":
        s=str(v).strip().lower()
        if s.endswith("mw"): attrs["power_w"]=int(float(s[:-2])*0.001)
        elif s.endswith("w"): attrs["power_w"]=int(float(s[:-1]))
    elif kl in ("connector","interface"):
        attrs["connector" if kl=="connector" else "interface"]=attr_aliases.get(str(v),str(v))
    elif kl == "color":
        attrs["color"]=str(v).lower()
    else:
        attrs[k]=v

entity = f"{brand.upper()}:{model}:{rec['category']}:pack{pack}"
print("model:", model, "pack:", pack, "attrs:", attrs, "entity:", entity)

result = {
  "source_sku": rec["source_sku"],
  "source_row": rec["row_id"],
  "source": rec["source"],
  "priority": source_priority[rec["source"]],
  "entity_id": entity,
  "reason": None,
  "brand": brand,
  "model": model,
  "category": rec["category"],
  "pack_size": pack,
  "attributes": attrs,
}
print(json.dumps(result, indent=2))
with open("/workspace/reference_work_result.json","w") as f:
    json.dump(result,f)
PY"}

